	internal static byte[] Compute(byte[] array)
	{
		ulong crc = ulong.MaxValue;
		ulong length = 0uL;
		HashCore(array, 0, array.Length, ref crc, ref length);
		return BitConverter.GetBytes(crc ^ length);
	}

	internal unsafe static void HashCore(byte[] array, int ibStart, int cbSize, ref ulong crc, ref ulong length)
	{
		int num = cbSize;
		int num2 = ibStart;
		fixed (ulong* ptr = table)
		{
			fixed (byte* ptr2 = array)
			{
				while (num >= 8)
				{
					crc ^= (ulong)(*(long*)(ptr2 + num2));
					crc = ptr[1792 + (crc & 0xFF)] ^ ptr[1536 + ((crc >> 8) & 0xFF)] ^ ptr[1280 + ((crc >> 16) & 0xFF)] ^ ptr[1024 + ((crc >> 24) & 0xFF)] ^ ptr[768 + ((crc >> 32) & 0xFF)] ^ ptr[512 + ((crc >> 40) & 0xFF)] ^ ptr[256 + ((crc >> 48) & 0xFF)] ^ ptr[crc >> 56];
					num2 += 8;
					num -= 8;
				}
				while (num > 0)
				{
					crc = ptr[(crc ^ ptr2[num2]) & 0xFF] ^ (crc >> 8);
					num2++;
					num--;
				}
			}
		}
		length += (ulong)cbSize;
	}
